package com.amaury.pointage

import android.content.Context
import android.graphics.*
import android.util.AttributeSet
import android.widget.Button
import kotlin.math.cos
import kotlin.math.min
import kotlin.math.sin

/** Moteur permanent des trois diamants de pointage. */
open class RedDiamondFinalButton @JvmOverloads constructor(
    context: Context, attrs: AttributeSet? = null, defStyleAttr: Int = android.R.attr.buttonStyle
) : Button(context, attrs, defStyleAttr) {
    companion object { const val RENDER_NAME = "Diamant rouge final"; private const val FACETS = 16 }
    private val fill=Paint(Paint.ANTI_ALIAS_FLAG); private val edge=Paint(Paint.ANTI_ALIAS_FLAG).apply{style=Paint.Style.STROKE}; private val glow=Paint(Paint.ANTI_ALIAS_FLAG); private val outer=Path(); private var lightAngle=-55f
    open fun diamondPalette()=intArrayOf(Color.rgb(255,50,76),Color.rgb(214,5,35),Color.rgb(132,0,24),Color.rgb(255,92,118),Color.rgb(92,0,20),Color.rgb(238,12,48),Color.rgb(178,0,31),Color.rgb(255,148,164),Color.rgb(110,0,25),Color.rgb(245,22,56),Color.rgb(156,0,29),Color.rgb(255,72,102),Color.rgb(74,0,18),Color.rgb(226,8,42),Color.rgb(194,0,34),Color.rgb(255,118,140))
    open fun diamondTint()=Color.rgb(255,28,62); open fun diamondDark()=Color.rgb(96,0,22); open fun diamondHighlight()=Color.rgb(255,238,243)
    init{background=null;stateListAnimator=null;setPadding(0,0,0,0);isAllCaps=false}
    fun setDiamondLightAngle(angle:Float){lightAngle=((angle%360f)+360f)%360f;invalidate()}
    override fun onDraw(c:Canvas){val w=width.toFloat();val h=height.toFloat();if(w<=0||h<=0)return;val cx=w*.5f;val cy=h*.5f;val r=min(w,h)*.465f;val press=if(isPressed).93f else 1f;c.save();c.scale(press,press,cx,cy);outer.reset();outer.addCircle(cx,cy,r,Path.Direction.CW);c.clipPath(outer);base(c,cx,cy,r);facets(c,cx,cy,r);refraction(c,cx,cy,r);edges(c,cx,cy,r);glint(c,cx,cy,r);c.restore();rim(c,cx,cy,r*press)}
    private fun base(c:Canvas,cx:Float,cy:Float,r:Float){val t=diamondTint();val d=diamondDark();fill.shader=RadialGradient(cx-r*.24f,cy-r*.30f,r*1.25f,intArrayOf(Color.argb(196,255.coerceAtMost(Color.red(t)+45),255.coerceAtMost(Color.green(t)+45),255.coerceAtMost(Color.blue(t)+45)),Color.argb(210,Color.red(t),Color.green(t),Color.blue(t)),Color.argb(218,Color.red(d),Color.green(d),Color.blue(d)),Color.argb(225,Color.red(d)/4,Color.green(d)/4,Color.blue(d)/4)),floatArrayOf(0f,.36f,.74f,1f),Shader.TileMode.CLAMP);c.drawCircle(cx,cy,r,fill);fill.shader=null}
    private fun facets(c:Canvas,cx:Float,cy:Float,r:Float){val ir=r*.30f;val mr=r*.64f;val or=r*.96f;for(i in 0 until FACETS){val a0=angle(i);val a1=angle(i+1);drawFacet(c,center(cx,cy,point(cx,cy,ir,a0),point(cx,cy,ir,a1)),i,normal(a0,a1),1.12f)};for(i in 0 until FACETS){val a0=angle(i);val a1=angle(i+1);val am=(a0+a1)*.5f;val i0=point(cx,cy,ir,a0);val i1=point(cx,cy,ir,a1);val m0=point(cx,cy,mr,a0);val m1=point(cx,cy,mr,a1);val mm=point(cx,cy,mr,am);drawFacet(c,poly(i0,m0,mm,i1),i+3,normal(a0,am),.92f);drawFacet(c,poly(i1,mm,m1),i+9,normal(am,a1),.82f)};for(i in 0 until FACETS){val a0=angle(i);val a1=angle(i+1);val am=(a0+a1)*.5f;val m0=point(cx,cy,mr,a0);val m1=point(cx,cy,mr,a1);val o0=point(cx,cy,or,a0);val o1=point(cx,cy,or,a1);val om=point(cx,cy,or,am);drawFacet(c,poly(m0,o0,om,m1),i+5,normal(a0,am),.72f);drawFacet(c,poly(m1,om,o1),i+12,normal(am,a1),.64f)}}
    private fun drawFacet(c:Canvas,p:Path,index:Int,n:Float,e:Float){val f=facing(n);val b=diamondPalette()[index%diamondPalette().size];val s=.34f+f*.94f*e;val rr=(Color.red(b)*s).toInt().coerceIn(0,255);val gg=(Color.green(b)*s).toInt().coerceIn(0,255);val bb=(Color.blue(b)*s).toInt().coerceIn(0,255);val a=(158+f*82).toInt().coerceIn(145,240);fill.shader=LinearGradient(0f,0f,width.toFloat(),height.toFloat(),Color.argb(a,rr,gg,bb),Color.argb((a*.70f).toInt(),(rr*.45f).toInt(),(gg*.45f).toInt(),(bb*.44f).toInt()),Shader.TileMode.CLAMP);c.drawPath(p,fill);fill.shader=null}
    private fun refraction(c:Canvas,cx:Float,cy:Float,r:Float){val rad=Math.toRadians(lightAngle.toDouble());val ux=cos(rad).toFloat();val uy=sin(rad).toFloat();val t=diamondTint();val hi=diamondHighlight();fill.shader=LinearGradient(cx-ux*r*.9f,cy-uy*r*.9f,cx+ux*r*.9f,cy+uy*r*.9f,intArrayOf(Color.TRANSPARENT,Color.argb(26,Color.red(t),Color.green(t),Color.blue(t)),Color.argb(132,Color.red(hi),Color.green(hi),Color.blue(hi)),Color.argb(62,Color.red(t),Color.green(t),Color.blue(t)),Color.TRANSPARENT),floatArrayOf(0f,.31f,.5f,.66f,1f),Shader.TileMode.CLAMP);c.drawCircle(cx,cy,r,fill);fill.shader=null}
    private fun edges(c:Canvas,cx:Float,cy:Float,r:Float){val hi=diamondHighlight();edge.strokeWidth=maxOf(1f,r*.0105f);edge.color=Color.argb(88,Color.red(hi),Color.green(hi),Color.blue(hi));for(i in 0 until FACETS){val a=angle(i);val p1=point(cx,cy,r*.30f,a);val p2=point(cx,cy,r*.64f,a);val p3=point(cx,cy,r*.96f,a);c.drawLine(cx,cy,p1[0],p1[1],edge);c.drawLine(p1[0],p1[1],p2[0],p2[1],edge);c.drawLine(p2[0],p2[1],p3[0],p3[1],edge)};edge.alpha=70;c.drawCircle(cx,cy,r*.30f,edge);c.drawCircle(cx,cy,r*.64f,edge);edge.alpha=255}
    private fun glint(c:Canvas,cx:Float,cy:Float,r:Float){val rad=Math.toRadians(lightAngle.toDouble());val x=cx+cos(rad).toFloat()*r*.48f;val y=cy+sin(rad).toFloat()*r*.48f;val hi=diamondHighlight();glow.shader=RadialGradient(x,y,r*.34f,intArrayOf(Color.argb(210,Color.red(hi),Color.green(hi),Color.blue(hi)),Color.argb(126,Color.red(hi),Color.green(hi),Color.blue(hi)),Color.argb(26,Color.red(diamondTint()),Color.green(diamondTint()),Color.blue(diamondTint())),Color.TRANSPARENT),floatArrayOf(0f,.18f,.54f,1f),Shader.TileMode.CLAMP);c.drawCircle(x,y,r*.34f,glow);glow.shader=null;edge.strokeWidth=maxOf(1f,r*.016f);edge.color=Color.argb(172,Color.red(hi),Color.green(hi),Color.blue(hi));c.drawLine(x-r*.12f,y,x+r*.12f,y,edge);c.drawLine(x,y-r*.12f,x,y+r*.12f,edge)}
    private fun rim(c:Canvas,cx:Float,cy:Float,r:Float){val d=diamondDark();val t=diamondTint();val hi=diamondHighlight();edge.style=Paint.Style.STROKE;edge.strokeWidth=maxOf(1.2f,r*.028f);edge.shader=SweepGradient(cx,cy,intArrayOf(d,hi,t,d,hi,t,d),null);c.drawCircle(cx,cy,r,edge);edge.shader=null}
    private fun facing(n:Float):Float{val delta=((lightAngle-n+540f)%360f)-180f;return((cos(Math.toRadians(delta.toDouble()))+1.0)*.5).toFloat()};private fun angle(i:Int)=-90f+i*(360f/FACETS);private fun normal(a:Float,b:Float)=(a+b)*.5f
    private fun point(cx:Float,cy:Float,r:Float,d:Float):FloatArray{val q=Math.toRadians(d.toDouble());return floatArrayOf(cx+cos(q).toFloat()*r,cy+sin(q).toFloat()*r)}
    private fun poly(vararg p:FloatArray)=Path().apply{moveTo(p[0][0],p[0][1]);for(i in 1 until p.size)lineTo(p[i][0],p[i][1]);close()};private fun center(cx:Float,cy:Float,vararg p:FloatArray)=Path().apply{moveTo(cx,cy);p.forEach{lineTo(it[0],it[1])};close()}
}
